-- 1. Penyesuaian skema tabel mitra
ALTER TABLE public.mitra ALTER COLUMN mitra_nip DROP NOT NULL;
ALTER TABLE public.mitra ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT now();

-- 2. Insert 85 Data Mitra
ON CONFLICT (id) DO UPDATE SET
  mitra_nip = EXCLUDED.mitra_nip,
  nama = EXCLUDED.nama,
  tahun = EXCLUDED.tahun,
  no_hp = EXCLUDED.no_hp,
  jabatan = EXCLUDED.jabatan,
  instansi = EXCLUDED.instansi;
